-- 2. Conditions Générales de Vente et mentions légales (versions du client)
INSERT INTO pages (slug, title, content, footer_group, published, sort) VALUES ('cgv', 'Conditions Générales de Vente', '<p><em>Conditions Générales de Vente en vigueur à compter du 1<sup>er</sup> octobre 2026.</em></p>\n\n<h2>Article 1 — Objet</h2>\n<p>Les présentes Conditions Générales de Vente régissent les ventes de produits et les demandes de services conclues à distance sur le site <strong>{domain}</strong> (ci-après « le Site »), exploité par <strong>{company_legal_name}</strong>, {address}, {company_ids} (ci-après « {company_name} » ou « le Vendeur »).</p>\n<p>Toute commande passée sur le Site implique l\'acceptation pleine et entière des présentes Conditions Générales de Vente, que le client reconnaît avoir lues avant de valider sa commande.</p>\n\n<h2>Article 2 — Clients</h2>\n<p>Le Site s\'adresse aux particuliers, professionnels, entreprises et administrations (ci-après « le Client »). Le Client déclare être majeur et disposer de la capacité juridique de contracter, ou être dûment habilité à engager la structure qu\'il représente.</p>\n<p>Les ventes en volume, les marchés publics et les contrats de location ou de maintenance peuvent faire l\'objet de conditions particulières (devis, bon de commande, contrat) qui prévalent alors sur les présentes Conditions Générales de Vente.</p>\n\n<h2>Article 3 — Produits</h2>\n<p>Les produits proposés (imprimantes multifonctions, copieurs, consommables, matériel informatique, papeterie et fournitures de bureau) sont décrits avec la plus grande exactitude possible. Les photographies, illustrations et caractéristiques sont communiquées à titre indicatif et n\'ont pas de valeur contractuelle.</p>\n<p>Les informations de compatibilité des consommables sont fournies sur la base des données des constructeurs. En cas de doute, le Client est invité à contacter {company_name} avant sa commande.</p>\n<p>Les offres sont valables dans la limite des stocks disponibles. La disponibilité est indiquée sur chaque fiche produit (« Stock disponible », « Stock faible », « Disponible sur commande », « Rupture de stock »).</p>\n\n<h2>Article 4 — Prix</h2>\n<p>Les prix sont indiqués en francs CFA (FCFA / XOF), toutes taxes comprises (TVA au taux en vigueur incluse), hors frais de livraison. Les frais de livraison sont précisés avant la validation de la commande.</p>\n<p>L\'affichage des prix en euros est proposé à titre purement indicatif, sur la base de la parité fixe 1 € = 655,957 FCFA. La commande est conclue et payée en francs CFA.</p>\n<p>{company_name} se réserve le droit de modifier ses prix à tout moment. Les produits sont facturés au prix en vigueur au moment de la validation de la commande. En cas d\'erreur manifeste de prix, {company_name} pourra annuler la commande après en avoir informé le Client, qui sera intégralement remboursé.</p>\n\n<h2>Article 5 — Commande</h2>\n<p>Le Client peut commander avec ou sans création de compte. Le processus de commande comprend les étapes suivantes : sélection des produits, vérification du panier, saisie des informations et de l\'adresse de livraison, choix du mode de livraison et du moyen de paiement, acceptation des Conditions Générales de Vente, puis validation et paiement.</p>\n<p>La validation de la commande vaut acceptation de son contenu et de son prix. Un email de confirmation récapitulant la commande est adressé au Client. {company_name} se réserve le droit d\'annuler ou de refuser toute commande d\'un Client avec lequel existerait un litige relatif au paiement d\'une commande antérieure, ou en cas de suspicion de fraude.</p>\n<p>Les codes promotionnels sont soumis à leurs conditions propres (durée de validité, montant minimum d\'achat, nombre d\'utilisations) et ne sont pas cumulables, sauf mention contraire.</p>\n\n<h2>Article 6 — Paiement</h2>\n<p>Le prix est payable en totalité à la commande, selon l\'un des moyens proposés :</p>\n<ul>\n<li><strong>Carte bancaire</strong> (Visa, Mastercard…), via les plateformes sécurisées Stripe ou PayDunya ;</li>\n<li><strong>Mobile money</strong> (Wave, Orange Money et autres moyens disponibles), via la plateforme sécurisée PayDunya ;</li>\n<li><strong>Paiement à la livraison</strong> ou <strong>virement bancaire</strong>, lorsque ces options sont proposées.</li>\n</ul>\n<p>Les données bancaires sont saisies directement sur les pages sécurisées des prestataires de paiement et ne sont jamais stockées par {company_name}. La commande est considérée comme payée après confirmation de l\'encaissement par le prestataire. En cas de refus ou d\'échec du paiement, la commande n\'est pas traitée.</p>\n\n<h2>Article 7 — Livraison et retrait</h2>\n<p>Les produits sont livrés à l\'adresse indiquée par le Client, dans les zones desservies au Sénégal. Les frais et délais indicatifs dépendent de la zone de livraison et sont précisés lors de la commande ; la livraison peut être offerte au-delà d\'un montant d\'achat indiqué sur le Site. Le Client peut également choisir le retrait gratuit à l\'adresse de retrait indiquée, lorsque cette option est proposée.</p>\n<p>Les délais de livraison sont donnés à titre indicatif. Un retard de livraison ne peut donner lieu à annulation de la commande ou à des dommages et intérêts, sauf retard supérieur à quinze (15) jours ouvrés non justifié, auquel cas le Client pourra demander l\'annulation et le remboursement de sa commande.</p>\n<p>Le Client est tenu de fournir des informations exactes et d\'être joignable au numéro indiqué. En cas d\'absence répétée ou d\'adresse erronée, des frais de nouvelle présentation peuvent être facturés.</p>\n\n<h2>Article 8 — Réception</h2>\n<p>Le Client vérifie l\'état des colis à la réception, en présence du livreur. Toute anomalie (colis endommagé, produit manquant ou non conforme) doit être mentionnée sur le bon de livraison et signalée à {company_name} dans un délai de quarante-huit (48) heures, par email à <a href=\"mailto:{email}\">{email}</a> ou par téléphone au {phones}, photographies à l\'appui.</p>\n\n<h2>Article 9 — Retours</h2>\n<p>Le Client peut demander le retour d\'un produit dans un délai de sept (7) jours à compter de sa réception, en contactant préalablement {company_name}. Le produit doit être retourné neuf, complet, dans son emballage d\'origine intact et non ouvert, accompagné de la facture. Les frais de retour sont à la charge du Client, sauf en cas d\'erreur ou de défaut imputable à {company_name}.</p>\n<p>Ne peuvent faire l\'objet d\'un retour : les consommables (toners, cartouches, encres, tambours) dont l\'emballage scellé a été ouvert, les produits commandés spécifiquement à la demande du Client (« sur commande »), les produits personnalisés, les logiciels descellés et les produits utilisés, endommagés ou incomplets du fait du Client.</p>\n<p>Après réception et contrôle du produit, le remboursement est effectué sous quatorze (14) jours, par le moyen de paiement utilisé lors de la commande ou, avec l\'accord du Client, sous forme d\'avoir.</p>\n\n<h2>Article 10 — Garanties</h2>\n<p>Les produits bénéficient de la garantie légale contre les vices cachés prévue par le Code des obligations civiles et commerciales, ainsi que, le cas échéant, de la garantie commerciale du constructeur dont la durée est indiquée sur la fiche produit.</p>\n<p>La garantie ne couvre pas les dommages résultant d\'une mauvaise utilisation, d\'une installation non conforme, de l\'usage de consommables inadaptés, d\'une surtension électrique, d\'une chute ou d\'une intervention par un tiers non agréé. Pour toute mise en œuvre de la garantie, le Client contacte le service client muni de sa facture.</p>\n\n<h2>Article 11 — Devis, location et maintenance</h2>\n<p>Les demandes de devis, d\'étude de location et de maintenance effectuées via le Site n\'engagent ni le Client ni {company_name}. Elles donnent lieu à une proposition commerciale ou à un contrat spécifique précisant les prix, durées, niveaux de service et conditions applicables.</p>\n\n<h2>Article 12 — Responsabilité</h2>\n<p>{company_name} est responsable de la bonne exécution de ses obligations. Sa responsabilité ne saurait être engagée en cas d\'inexécution imputable au Client, au fait imprévisible et insurmontable d\'un tiers, ou à un cas de force majeure tel que défini par la loi et la jurisprudence. En toute hypothèse, et sauf disposition légale impérative contraire, sa responsabilité est limitée au montant de la commande concernée et ne couvre pas les dommages indirects (perte de données, perte d\'exploitation, manque à gagner).</p>\n<p>Il appartient au Client de sauvegarder ses données avant toute intervention technique ou tout retour de matériel.</p>\n\n<h2>Article 13 — Données personnelles</h2>\n<p>Les données collectées lors de la commande sont nécessaires à son traitement et à la relation commerciale. Elles sont traitées conformément à la loi n° 2008-12 du 25 janvier 2008 portant sur la protection des données à caractère personnel et à notre <a href=\"{site_url}/confidentialite\">Politique de confidentialité</a>.</p>\n\n<h2>Article 14 — Preuve et archivage</h2>\n<p>Les registres informatisés de {company_name}, conservés dans des conditions raisonnables de sécurité, sont considérés comme la preuve des communications, commandes et paiements intervenus entre les parties, conformément à la loi n° 2008-08 du 25 janvier 2008 sur les transactions électroniques. Les factures sont accessibles depuis l\'espace client.</p>\n\n<h2>Article 15 — Service client et réclamations</h2>\n<p>Pour toute information, réclamation ou demande relative à une commande : <a href=\"mailto:{email}\">{email}</a> — {phones} — {address}.</p>\n\n<h2>Article 16 — Droit applicable et litiges</h2>\n<p>Les présentes Conditions Générales de Vente sont soumises au droit sénégalais. En cas de litige, les parties s\'efforceront de trouver une solution amiable. À défaut, le litige sera porté devant les juridictions compétentes de Dakar, sous réserve des règles impératives applicables aux consommateurs.</p>\n\n<h2>Article 17 — Modification des Conditions Générales de Vente</h2>\n<p>{company_name} se réserve le droit de modifier les présentes Conditions Générales de Vente à tout moment. Les Conditions Générales de Vente applicables sont celles en vigueur à la date de validation de la commande.</p>\n', 'legal', 1, 1)
ON DUPLICATE KEY UPDATE title = VALUES(title), content = VALUES(content), published = 1;
INSERT INTO pages (slug, title, content, footer_group, published, sort) VALUES ('mentions-legales', 'Mentions légales', '<p>Conformément à la loi n° 2008-08 du 25 janvier 2008 sur les transactions électroniques, les informations suivantes sont portées à la connaissance des utilisateurs du site <strong>{domain}</strong> (ci-après « le Site »).</p>\n\n<h2>1. Éditeur du site</h2>\n<p>Le Site <strong>{site_name}</strong> est édité par :</p>\n<ul>\n<li><strong>{company_legal_name}</strong></li>\n<li>Siège social : {address}</li>\n<li>Identifiants légaux : {company_ids}</li>\n<li>Téléphone : {phones}</li>\n<li>Email : <a href=\"mailto:{email}\">{email}</a></li>\n</ul>\n<p><strong>Directeur de la publication :</strong> {legal_representative}.</p>\n<p>AFAM Print &amp; Services SARL est une entreprise sénégalaise spécialisée dans les solutions d\'impression, la vente et la location d\'imprimantes multifonctions, ainsi que la maintenance et la fourniture de consommables.</p>\n\n<h2>2. Conception et développement</h2>\n<p>Le Site a été conçu et développé par la société <strong>Neosen</strong> — <a href=\"https://neosen.tech\" target=\"_blank\" rel=\"noopener\">neosen.tech</a>.</p>\n<ul>\n<li>Gérant : <strong>Cheikh Tidiane MBAYE</strong></li>\n<li>Site web : <a href=\"https://neosen.tech\" target=\"_blank\" rel=\"noopener\">https://neosen.tech</a></li>\n</ul>\n<p>Neosen intervient en qualité de prestataire technique. Le contenu publié sur le Site (produits, prix, textes, images) relève de la seule responsabilité de l\'éditeur.</p>\n\n<h2>3. Hébergement</h2>\n<p>{host_info}</p>\n\n<h2>4. Propriété intellectuelle</h2>\n<p>L\'ensemble des éléments composant le Site (structure, textes, illustrations, logos, graphismes, base de données, logiciels) est la propriété exclusive de {company_name} ou fait l\'objet d\'une autorisation d\'utilisation. Toute reproduction, représentation, modification ou exploitation, totale ou partielle, sans autorisation écrite préalable est interdite et constitue une contrefaçon.</p>\n<p>Les marques citées sur le Site (notamment Sharp, Canon, HP, Ricoh) ainsi que les visuels des produits appartiennent à leurs propriétaires respectifs et sont utilisés à seule fin d\'identification des produits proposés à la vente.</p>\n\n<h2>5. Responsabilité</h2>\n<p>{company_name} s\'efforce d\'assurer l\'exactitude et la mise à jour des informations diffusées sur le Site, mais ne peut garantir l\'absence d\'erreurs ou d\'omissions. Les photographies et descriptions des produits sont fournies à titre indicatif et ne sont pas contractuelles.</p>\n<p>{company_name} ne saurait être tenue responsable des dommages résultant d\'une interruption du Site, d\'un dysfonctionnement technique, de l\'intrusion d\'un tiers ou de l\'utilisation d\'un matériel informatique inadapté par l\'utilisateur.</p>\n<p>Les liens vers des sites tiers sont proposés pour la commodité des utilisateurs ; {company_name} n\'exerce aucun contrôle sur ces sites et décline toute responsabilité quant à leur contenu.</p>\n\n<h2>6. Données personnelles et cookies</h2>\n<p>Le traitement des données personnelles collectées sur le Site est décrit dans la <a href=\"{site_url}/confidentialite\">Politique de confidentialité</a>, conformément à la loi n° 2008-12 du 25 janvier 2008 portant sur la protection des données à caractère personnel. L\'utilisation des cookies est détaillée dans la <a href=\"{site_url}/cookies\">Politique de cookies</a>.</p>\n\n<h2>7. Droit applicable</h2>\n<p>Les présentes mentions légales sont régies par le droit sénégalais. Tout litige relatif à l\'utilisation du Site relève, à défaut de règlement amiable, de la compétence des juridictions de Dakar.</p>\n\n<h2>8. Contact</h2>\n<p>Pour toute question relative au Site : <a href=\"mailto:{email}\">{email}</a> — {phones}.</p>\n', 'legal', 1, 2)
ON DUPLICATE KEY UPDATE title = VALUES(title), content = VALUES(content), published = 1;

-- 3. Page « Impression multisupport »
UPDATE services SET content = '<div class=\"svc-intro\">\n<p class=\"lead\">Au-delà de l\'équipement de vos bureaux, <strong>{company_name}</strong> réalise tous vos supports imprimés professionnels : communication, événementiel, signalétique et objets personnalisés, en petite comme en grande série, avec un rendu soigné et des délais maîtrisés.</p>\n</div>\n\n<h2>Nos impressions</h2>\n<div class=\"svc-grid\">\n<div class=\"svc-card svc-card-sm\">\n<div class=\"svc-visual\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><path d=\"M14 2v6h6M8 13h8M8 17h5\"/></svg></div>\n<div class=\"svc-body\"><h3>Flyers et dépliants</h3><p>Flyers, dépliants, prospectus et brochures pour vos campagnes et événements, en petites ou grandes quantités.</p></div>\n</div>\n<div class=\"svc-card svc-card-sm\">\n<div class=\"svc-visual\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><circle cx=\"8\" cy=\"11\" r=\"2\"/><path d=\"M5 16c.6-1.6 1.7-2.4 3-2.4s2.4.8 3 2.4M14 10h5M14 14h4\"/></svg></div>\n<div class=\"svc-body\"><h3>Cartes de visite</h3><p>Cartes de visite professionnelles, recto ou recto-verso, avec finitions mates, brillantes ou pelliculées.</p></div>\n</div>\n<div class=\"svc-card svc-card-sm\">\n<div class=\"svc-visual\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M20 12v10H4V12M2 7h20v5H2zM12 22V7M12 7H7.5a2.5 2.5 0 0 1 0-5C11 2 12 7 12 7zM12 7h4.5a2.5 2.5 0 0 0 0-5C13 2 12 7 12 7z\"/></svg></div>\n<div class=\"svc-body\"><h3>Goodies et objets publicitaires</h3><p>Stylos, mugs, porte-clés, clés USB, tote bags et objets personnalisés à votre image.</p></div>\n</div>\n<div class=\"svc-card svc-card-sm\">\n<div class=\"svc-visual\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 2l3 7h7l-5.5 4.5L18.5 21 12 16.5 5.5 21l2-7.5L2 9h7z\"/></svg></div>\n<div class=\"svc-body\"><h3>Branding</h3><p>Identité visuelle déclinée sur tous vos supports : papeterie d\'entreprise, chemises, enveloppes, signalétique.</p></div>\n</div>\n<div class=\"svc-card svc-card-sm\">\n<div class=\"svc-visual\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M7 2h10v16H7zM12 18v3M8 21h8\"/><path d=\"M9 6h6M9 9h4\"/></svg></div>\n<div class=\"svc-body\"><h3>Kakémonos et roll-up</h3><p>Kakémonos, roll-up et totems pour vos salons, accueils, agences et événements.</p></div>\n</div>\n<div class=\"svc-card svc-card-sm\">\n<div class=\"svc-visual\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M20.4 6.4 16 4a4 4 0 0 1-8 0L3.6 6.4a1 1 0 0 0-.5 1.2l1.1 3.4a1 1 0 0 0 1.2.6L7 11v10h10V11l1.6.6a1 1 0 0 0 1.2-.6l1.1-3.4a1 1 0 0 0-.5-1.2z\"/></svg></div>\n<div class=\"svc-body\"><h3>Impression sur vêtements</h3><p>T-shirts, polos, casquettes et tenues de travail personnalisés (sérigraphie, flocage, broderie selon le support).</p></div>\n</div>\n<div class=\"svc-card svc-card-sm\">\n<div class=\"svc-visual\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M20.6 13.4 13.4 20.6a2 2 0 0 1-2.8 0L2 12V2h10l8.6 8.6a2 2 0 0 1 0 2.8z\"/><circle cx=\"7\" cy=\"7\" r=\"1.5\"/></svg></div>\n<div class=\"svc-body\"><h3>Étiquettes</h3><p>Étiquettes produits, adhésives ou en rouleaux, codes-barres et étiquetage logistique.</p></div>\n</div>\n<div class=\"svc-card svc-card-sm\">\n<div class=\"svc-visual\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"2\" y=\"6\" width=\"20\" height=\"11\" rx=\"1\"/><circle cx=\"4.5\" cy=\"8.5\" r=\".8\"/><circle cx=\"19.5\" cy=\"8.5\" r=\".8\"/><circle cx=\"4.5\" cy=\"14.5\" r=\".8\"/><circle cx=\"19.5\" cy=\"14.5\" r=\".8\"/><path d=\"M7 11.5h10\"/></svg></div>\n<div class=\"svc-body\"><h3>Bâches et banderoles</h3><p>Bâches grand format, banderoles et affichage extérieur résistant, avec œillets pour la pose.</p></div>\n</div>\n<div class=\"svc-card svc-card-sm\">\n<div class=\"svc-visual\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M15.5 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h9.5L21 14.5V5a2 2 0 0 0-2-2z\"/><path d=\"M14 21v-5a2 2 0 0 1 2-2h5\"/></svg></div>\n<div class=\"svc-body\"><h3>Autocollants et stickers</h3><p>Autocollants, stickers découpés à la forme, vitrophanie et marquage de véhicules.</p></div>\n</div>\n</div>\n\n<h2>Notre accompagnement</h2>\n<div class=\"about-grid\">\n<div class=\"about-card\"><h3>Conseil</h3><p>Choix des supports, formats, quantités et finitions selon votre usage et votre budget.</p></div>\n<div class=\"about-card\"><h3>Création et mise en page</h3><p>Mise en forme à partir de vos éléments ou déclinaison de votre charte graphique.</p></div>\n<div class=\"about-card\"><h3>Bon à tirer</h3><p>Vérification de vos fichiers et validation d\'un bon à tirer avant toute impression.</p></div>\n<div class=\"about-card\"><h3>Livraison</h3><p>Retrait sur place ou livraison à Dakar et dans les régions.</p></div>\n</div>\n\n<div class=\"about-cta\">\n<h2>Un projet d\'impression ?</h2>\n<p>Décrivez votre besoin dans le formulaire (type de support, format, quantité, délai) et joignez vos fichiers : nous vous adressons un devis rapidement.</p>\n<p><a class=\"btn btn-accent\" href=\"#formulaire\">Demander un devis</a> <a class=\"btn btn-outline\" href=\"tel:{phone_link}\">Appeler le {phone}</a></p>\n</div>\n', short_desc = 'Flyers, cartes de visite, goodies, branding, kakémonos, vêtements, étiquettes, bâches, autocollants : tous vos imprimés professionnels.' WHERE slug = 'impression-multisupport';

