INSERT IGNORE INTO categories (parent_id, name, slug, description, image, icon, sort, show_in_menu, active)
SELECT NULL, 'Cadeaux de fin d''année', 'cadeaux-fin-annee', '<p>Faites plaisir à vos collaborateurs, clients et partenaires avec des <strong>cadeaux de fin d\'année utiles et personnalisés</strong> : mugs à votre logo, packs high-tech pour le bureau, la mobilité ou le télétravail, coffrets gourmands avec machine à café.</p><p>Chaque cadeau peut être <strong>personnalisé à vos couleurs</strong> (logo, message, emballage). Composition, quantités et tarifs <strong>sur devis</strong> : cliquez sur « Demander un devis » depuis le produit de votre choix.</p>', 'assets/img/contenus/cat-cadeaux.jpg', 'gift', COALESCE(MAX(c.sort), 0) + 1, 1, 1 FROM (SELECT sort FROM categories WHERE parent_id IS NULL) c;

