INSERT IGNORE INTO products (sku, name, slug, category_id, product_type, short_description, description, specs, price, stock, delivery_delay, published)
SELECT 'AF-CAD-MUG', 'Mugs personnalisés', 'mugs-personnalises', id, 'Mug', 'Mugs en céramique personnalisés à votre logo ou avec votre message, livrables en boîte cadeau.', '<p>Le cadeau d\'entreprise incontournable : un mug utilisé au quotidien, qui porte votre image.</p><ul><li>Mug en céramique, impression haute définition résistante</li><li>Personnalisation : logo, message, prénom du destinataire</li><li>Plusieurs coloris disponibles</li><li>Emballage cadeau individuel en option</li></ul><p>Tarif dégressif selon les quantités : demandez votre devis.</p>', 'Personnalisation: Logo, message, prénom\nMatière: Céramique\nConditionnement: Boîte cadeau en option\nTarif: Sur devis selon quantité', 0, 0, 'Selon quantité et personnalisation', 1 FROM categories WHERE slug = 'cadeaux-fin-annee';
INSERT INTO product_images (product_id, path, alt, is_main, sort) SELECT p.id, 'assets/img/contenus/cadeau-mugs.jpg', 'Mugs personnalisés', 1, 0 FROM products p WHERE p.sku = 'AF-CAD-MUG' AND NOT EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = p.id);
